const DATA={"goals": [["G-PREV", "Act before harm builds", "\"many agencies can act before harm builds\"", "Increased preventive capacity", "2 · One sky, many readers", "Now a goal for every agency in the commons, not only CDPH."], ["G-EQUITY", "Protection first, and a fair share of the sky", "\"protection reaching the most burdened blocks first, no block carrying more than its share of the sky\"", "Environmental health equity", "1 · Flights pay their way", "Two sides: fair benefit (who gets protected first) and fair burden (who carries the flights)."], ["G-POWER", "Answerable to the people beneath it", "\"every reading answerable to the people beneath it\"", "Community power", "3 · The sky answers to the street", "Residents as readers and deciders, not only subjects."]], "aff": [["AF-COVER", "Coverage by need", "Any agency can place sensing where burden is highest, not only where flights already are.", "EQ-1", "G-EQUITY, G-PREV", "1", "Carried. Now any agency, through the protected share.", "I-DISPAR, I-BLIND, I-INSPBIAS"], ["AF-GAPS", "Gap visibility", "Anyone reading the base map can see where data is thin, on any layer.", "EQ-2", "G-EQUITY", "2", "Carried.", "I-BLIND"], ["AF-AIRSPACE", "Airspace allocation", "The city can shape who flies where, with what priority and burden.", "EQ-3, AS-1, AS-3", "G-EQUITY", "1", "Carried. Was an orphan under CDPH's goals; fits at city level.", "I-OVERFLY, I-STAKE"], ["AF-DETECT", "Early detection", "An agency notices a change, and knows when it obliges action, before harm builds.", "PV-1", "G-PREV", "2", "Carried.", "I-INSPBIAS, I-EXPOSE, I-LEAD"], ["AF-RELY", "Data reliability", "Analysts can trust and combine readings from many sources, operators included.", "PV-2", "G-PREV", "2", "Carried. Adds checks on operator data.", "I-LEAD, I-FALSE"], ["AF-REDUN", "Redundancy", "Sensing keeps working when drones are grounded or a source fails.", "PV-3", "G-PREV", "2", "Carried. One fallback for every agency.", "I-CONTIN"], ["AF-MOBIL", "Mobilization", "Responders move people and supplies quickly once a signal is confirmed.", "PV-4", "G-PREV", "C", "Carried. Stays each agency's own.", "I-EXPOSE, I-SPEED"], ["AF-ROUTE", "Routing to domain owner", "A signal reaches the office with authority to act, whoever collected it.", "PV-4", "G-PREV", "2", "Carried. Core of the shared queue.", "I-ORPHAN"], ["AF-REHEARSE", "Rehearsal", "Agencies and residents practice a response or decision before it is needed.", "PV-5", "G-PREV", "2", "Carried. Now joint.", "I-STAKE, I-SPEED"], ["AF-MEMORY", "Memory", "An agency can read this event against past ones.", "PV-5", "G-PREV", "C", "Carried.", "I-LEARN"], ["AF-PARTNER", "Partnership", "Operators and agencies exchange flights, data and services on terms both keep.", "PV-6", "G-PREV", "1", "Carried. Now the city's terms, not CDPH's.", "I-COORD, I-DISPAR"], ["AF-SHOW", "Displaying information", "Residents and staff can read what is measured and what it means.", "PW-1", "G-POWER, G-PREV", "3", "Carried.", "I-AWARE, I-TRUST"], ["AF-TRACE", "Traceability", "Anyone can reconstruct who flew, what was sensed, who looked and what was done.", "PW-2", "G-POWER, G-PREV", "3", "Carried. Widened to flights and access, not just readings.", "I-ACCT, I-LEARN, I-READERS"], ["AF-PART", "Participation", "Residents can report, request, challenge and decide, and get an answer.", "PW-3", "G-POWER", "3", "Carried. Adds requesting and panel decisions.", "I-STAKE, I-TRUST"], ["AF-ACCESS", "Control access", "Communities and the custodian limit who sees data, at what grain.", "PW-4", "G-POWER", "3", "Carried.", "I-TRUST, I-SURV"], ["AF-SHARE", "Shared capacity", "One flight, one map and one fallback serve many agencies at once.", "CM-1", "G-PREV", "2", "New (11.02).", "I-SHARECOST, I-COORD"], ["AF-PURPOSE", "Purpose limitation", "A reading stays bound to why it was collected; new purposes need a public decision.", "CM-2", "G-POWER", "3", "New (11.02).", "I-SURV, I-TRUST"], ["AF-ALLOC", "Allocation", "When agencies want the same flight, fleet or airspace, a named rule decides.", "AS-2 (partly); no full criterion yet", "G-EQUITY, G-PREV", "2", "New (11.02). Criterion still to write.", "I-SETTLED"], ["AF-BURDEN", "Burden accounting", "Burden is counted across every agency's flights, so no one block carries more than its share.", "CM-3", "G-EQUITY", "1", "New (11.02).", "I-OVERFLY, I-CAP"]], "imp": [["I-DISPAR", "Decreased exposure disparity", "Burdened neighborhoods breathe air closer to everyone else's.", "Intended", "G-EQUITY, G-PREV", "", "AF-COVER, AF-PARTNER", "", "1", "Carried"], ["I-BLIND", "Decreased hidden blind spots", "Thin data is visible and gets filled.", "Intended", "G-EQUITY", "", "AF-COVER, AF-GAPS", "", "2", "Carried"], ["I-INSPBIAS", "Decreased complaint-driven inspection bias", "Inspections follow burden, not who complains.", "Intended", "G-EQUITY, G-PREV", "", "AF-COVER, AF-DETECT", "", "C", "Carried"], ["I-OVERFLY", "Decreased overflight burden disparity", "Flights spread fairly across neighborhoods, counted across every agency.", "Intended", "G-EQUITY", "", "AF-AIRSPACE, AF-BURDEN", "", "1", "Widened to all agencies"], ["I-STAKE", "Increased health stake in airspace decisions", "Health is weighed when corridors and hubs are sited.", "Intended", "G-EQUITY, G-PREV", "", "AF-AIRSPACE, AF-REHEARSE, AF-PART", "", "1", "Carried"], ["I-EXPOSE", "Decreased exposure events", "Fewer people are exposed before anyone acts.", "Intended", "G-PREV", "", "AF-DETECT, AF-MOBIL", "", "C", "Carried"], ["I-LEAD", "Decreased lead time from signal to action", "Less time between a reading and a response.", "Intended", "G-PREV", "", "AF-DETECT, AF-RELY", "", "2", "Carried"], ["I-FALSE", "Decreased false alerts", "Fewer wrong dispatches.", "Intended", "G-PREV", "", "AF-RELY", "", "2", "Carried"], ["I-CONTIN", "Increased continuity of awareness", "The picture stays on during groundings.", "Intended", "G-PREV", "", "AF-REDUN", "", "2", "Carried"], ["I-COORD", "Increased coordination", "Agencies act on one picture instead of six.", "Intended", "G-PREV", "", "AF-PARTNER, AF-SHARE", "", "2", "Carried"], ["I-SPEED", "Increased response speed", "Rehearsed roles move faster.", "Intended", "G-PREV", "", "AF-REHEARSE, AF-MOBIL", "", "C", "Carried"], ["I-LEARN", "Increased institutional learning", "Each event changes what happens next time.", "Intended", "G-PREV", "", "AF-MEMORY, AF-TRACE", "", "2", "Carried"], ["I-ORPHAN", "Decreased orphaned signals", "No reading sits unowned.", "Intended", "G-PREV", "", "AF-ROUTE", "", "2", "Carried"], ["I-AWARE", "Increased public awareness", "Residents know what is in their air.", "Intended", "G-POWER, G-PREV", "", "AF-SHOW", "", "3", "Carried"], ["I-TRUST", "Increased community trust and legitimacy", "Residents believe the system works for them.", "Intended", "G-POWER", "", "AF-SHOW, AF-PART, AF-ACCESS, AF-PURPOSE", "", "3", "Carried"], ["I-SURV", "Decreased surveillance risk", "Health data cannot drift into enforcement.", "Intended", "G-POWER", "", "AF-ACCESS, AF-PURPOSE", "", "3", "Carried"], ["I-ACCT", "Increased accountability", "Every action can be traced to who decided.", "Intended", "G-POWER", "", "AF-TRACE", "", "3", "Carried"], ["I-SHARECOST", "Lower cost per agency for airspace sensing", "Each agency sees the airspace for less than going alone.", "Intended", "G-PREV", "", "AF-SHARE", "", "2", "New"], ["I-READERS", "Residents read the airspace", "Anyone can see who flew over their block, when and why.", "Intended", "G-POWER", "", "AF-TRACE, AF-SHOW", "", "3", "New"], ["I-SETTLED", "Conflicts settled by rule, not by budget", "The biggest agency no longer sets the coverage map.", "Intended", "G-EQUITY, G-PREV", "", "AF-ALLOC", "", "2", "New"], ["I-CAP", "Burden held within each block's share", "No neighborhood carries more than its share of the sky.", "Intended", "G-EQUITY", "", "AF-BURDEN", "", "1", "New"], ["U-OVERFLY", "More overflights over burdened areas", "Need-weighted sensing sends more flights to the same blocks.", "Unintended", "", "G-EQUITY", "AF-COVER, AF-PARTNER", "Burden budget (PT-BUDGET); shared pods", "1", "Carried"], ["U-FATIGUE", "Alert fatigue", "Too many alerts, and people stop listening.", "Unintended", "", "G-PREV, G-POWER", "AF-DETECT, AF-SHOW", "Confirmation before alerts (R-TRIG); escalation levels", "C", "Carried"], ["U-CREEP", "Surveillance creep", "Long histories and many readers raise the stakes of misuse.", "Unintended", "", "G-POWER", "AF-MEMORY, AF-COVER, AF-SHARE", "Purpose labels and access matrix (PT-PURPOSE)", "3", "Carried"], ["U-REFUSE", "Deliberate blind spots from refusals", "A refusal leaves harm unmeasured in a burdened block.", "Unintended", "", "G-PREV, G-EQUITY", "AF-ACCESS, AF-PURPOSE", "Health readings stay advisory; ground sensors (archetypes 2 and 1)", "3", "Carried, widened"], ["U-GROWTH", "Incentive to fly more", "The commons gets more valuable with every flight.", "Unintended", "", "G-EQUITY", "AF-PARTNER, AF-SHARE", "Burden budget; panels can ask for lower budgets (archetype 3)", "1", "New"], ["U-GOODWILL", "Operator goodwill runs out", "Too many asks, and operators push back or move hubs outside the city.", "Unintended", "", "G-PREV", "AF-PARTNER", "One front door, menu and cap on asks (archetype 2)", "1", "New"], ["U-STACK", "Burden stacks up across agencies", "Each agency's flights look fine alone and too many together.", "Unintended", "", "G-EQUITY", "AF-SHARE, AF-COVER", "Burden accounting across agencies (PT-BUDGET)", "2", "New"], ["U-AVOID", "Service avoidance", "Operators route around capped blocks, so places with little service get less.", "Unintended", "", "G-EQUITY", "AF-BURDEN", "Watched in the ledger; panel exceptions (archetype 3)", "1", "New"], ["U-PURPOSEGROW", "Purposes grow through budget decisions", "The program widens without anyone breaking a data rule (the Hayden AI pattern).", "Unintended", "", "G-POWER", "AF-SHARE, AF-PARTNER", "Rule for adding purposes (R-NEWUSE); panels", "3", "New"], ["U-CONCENTRATE", "One failure exposes every agency", "A shared map is a shared point of failure.", "Unintended", "", "G-POWER, G-PREV", "AF-SHARE", "Separate layers; continuity plan covers the platform", "2", "New"]], "feats": [{"id": "P-INSP", "name": "Environmental Inspection Office", "type": "P", "change": "Keep", "what": "CDPH's inspectors and the specialist who ranks sites by burden. Their day is the moment the whole project started from: a list set by who complained, not by where harm is.", "pa": "AF-COVER", "sa": "AF-DETECT", "layer": "Agency use", "why": "No change. Stays CDPH's own and reads the health layer through the access rules.", "protos": "PT-INSPECT, PT-MANDATE, PT-ANCHOR", "q": null}, {"id": "P-EPI", "name": "Epidemiology Office", "type": "P", "change": "Keep, new role", "what": "Epidemiologists who read the health layer, confirm signals and keep the archive. They now also bring the health measures into the city's burden definition.", "pa": "AF-DETECT", "sa": "AF-BURDEN", "layer": "Agency use", "why": "New job: CDPH writes the health part of \"burden\", not the whole thing, because CDPH also spends from the budget.", "protos": "PT-MEMORY, BASE-TWIN", "q": null}, {"id": "P-PREP", "name": "Emergency Preparedness Office", "type": "P", "change": "Keep, new role", "what": "Preparedness staff who run exercises and write CDPH's criteria for asking the city to switch into emergency mode.", "pa": "AF-REHEARSE", "sa": "AF-MOBIL", "layer": "Agency use", "why": "CDPH no longer declares its own health priority. It asks OEMC, using criteria written ahead of time.", "protos": "PT-EXERCISE, PT-PRIORITY", "q": null}, {"id": "P-CHW", "name": "Community Health Workers", "type": "P", "change": "Keep", "what": "Health workers who sit with residents, read results with them on a schedule and help confirm signals.", "pa": "AF-SHOW", "sa": "AF-PART", "layer": "Agency use", "why": "No change. Part of CDPH's own way of responding; other agencies bring their own people.", "protos": "PT-CREWS, PT-MESSENGER, PT-EXERCISE, PT-VERIFIED", "q": null}, {"id": "P-RELAY", "name": "Community Relay Network", "type": "P", "change": "Keep", "what": "Clinics, tenant groups, schools and churches that carry findings out and take a part in the response.", "pa": "AF-SHOW", "sa": "AF-PART", "layer": "Agency use", "why": "Moves out of the shared layers. The Mural lists trusted messengers as CDPH-only.", "protos": "PT-CREWS, PT-MESSENGER", "q": null}, {"id": "P-RES", "name": "Residents (readers and requesters)", "type": "P", "change": "Redesign", "what": "People living under the flights. They can now see who flew over them and why, ask for sensing themselves, and refuse new kinds of use through their neighborhood panel.", "pa": "AF-PART", "sa": "AF-TRACE", "layer": "Governance", "why": "Residents were mostly on the receiving end: alerts, challenges, hosting sensors. The Mural asked for them to read the airspace too.", "protos": "PT-RECORD, PT-VERIFIED, PT-TRUST", "q": "Who pays for residents' own sensing requests?"}, {"id": "P-TRUST", "name": "Data Custodian Board", "type": "P", "change": "Redesign", "what": "An independent board with resident seats. It holds the data, keeps the list of allowed purposes, approves the burden definition and checks who looked at what.", "pa": "AF-ACCESS", "sa": "AF-PURPOSE", "layer": "Governance", "why": "Was a trust with a veto on every use. Now decides at the level of purposes, and neighborhoods decide which purposes their share of the sky goes to. This gives up some per-use control for a body every agency can work with.", "protos": "PT-TRUST", "q": "Does the board need a Council ordinance to have real authority?"}, {"id": "P-PANEL", "name": "Neighborhood Use Panels", "type": "P", "change": "New", "what": "A small resident body in each neighborhood that says yes or no to the kinds of use its sky is spent on. Its word is binding on cameras and anything near enforcement, and advisory on sensor-only health and environment uses.", "pa": "AF-PART", "sa": "AF-ACCESS", "layer": "Governance", "why": "Fair benefit means different things to different agencies (CDPH and CPD read it in opposite ways). The people under the flights decide, by purpose, not flight by flight. Follows Oakland's front-end review; avoids the advisory-only fatigue seen in California's AB 617 committees.", "protos": "PT-TRUST, PT-PURPOSE (new)", "q": "Who sits on a panel, and how is a neighborhood drawn?"}, {"id": "P-HOST", "name": "Platform Host (DTI)", "type": "P", "change": "New", "what": "The city office that runs the shared system day to day: the base map, the router, the ledger. Our working answer is the Department of Technology and Innovation.", "pa": "AF-SHARE", "sa": "AF-TRACE", "layer": "Governance", "why": "The Mural's gap: \"Nobody owns the multi-agency picture.\" Running it and deciding who may use the data stay with different bodies.", "protos": "PT-PURPOSE (new), PT-TERMS (new)", "q": "Does DTI have the mandate and staff, or is a new cross-department body needed?"}, {"id": "P-UNIV", "name": "University Modeling Partner", "type": "P", "change": "Keep", "what": "Builds and maintains the base map and scenario models under ethics review.", "pa": "AF-RELY", "sa": "AF-REHEARSE", "layer": "Shared base", "why": "No change.", "protos": "PT-WATCH, PT-EXERCISE, BASE-TWIN", "q": null}, {"id": "P-FLEET", "name": "Partner Agency Fleet", "type": "P", "change": "Keep", "what": "Other public agencies' drones and pilots, lent under standing agreements.", "pa": "AF-REDUN", "sa": "AF-ALLOC", "layer": "Operator terms", "why": "Same feature, with the conflict named: CFD needs its drones in the same heat waves and plumes CDPH does. In an emergency, OEMC decides.", "protos": "PT-FALLBACK, PT-TASKDESK, PT-PRIORITY", "q": "Does health keep a protected share of the fleet in emergency mode?"}, {"id": "P-OPS", "name": "Commercial Drone Operators", "type": "P", "change": "Keep, new role", "what": "Delivery and inspection companies and the routing software that decides where their flights go. The commercial flight network is the base every agency rides on.", "pa": "AF-PARTNER", "sa": "AF-SHARE", "layer": "Operator terms", "why": "Now engaged at three levels: Base 1 (required), Base 2 (traded), add-ons (asked for). The city's goodwill with operators is the real scarce resource.", "protos": "PT-TERMS (new), PT-PODS, PT-HUBS", "q": null}, {"id": "P-UAS", "name": "CDPH Drone Program", "type": "P", "change": "Option, never prototyped", "what": "CDPH flying its own aircraft on missions it schedules itself.", "pa": "AF-COVER", "sa": "AF-RELY", "layer": "Operator terms", "why": "Still an option. Weaker now: the commons exists so agencies don't each need a fleet.", "protos": "none", "q": null}, {"id": "P-XDEPT", "name": "Cross-Department Response Team", "type": "P", "change": "Keep", "what": "City staff shared across departments who carry out a response.", "pa": "AF-MOBIL", "sa": "AF-ROUTE", "layer": "Governance", "why": "No change.", "protos": "BASE-RESPONSE", "q": null}, {"id": "P-OEMC", "name": "OEMC", "type": "P", "change": "Keep, new role", "what": "Chicago's emergency management office. In a declared emergency it decides who flies first.", "pa": "AF-ALLOC", "sa": "AF-MOBIL", "layer": "Governance", "why": "New job: the named arbiter. Only one actor can hold a piece of airspace at a time, so emergency priority cannot be shared or mirrored.", "protos": "PT-PRIORITY", "q": "Will OEMC accept this role?"}, {"id": "P-AIRAUTH", "name": "Airspace Authorities (FAA, USS)", "type": "P", "change": "Keep", "what": "The FAA and airspace service suppliers, who hold the flight rules the city can only influence.", "pa": "AF-AIRSPACE", "sa": null, "layer": "Governance", "why": "No change. The city's real levers stay on the ground: sites, permits, hubs.", "protos": "PT-CORRIDOR, PT-PRIORITY", "q": "Do payload changes on commercial aircraft need FAA approval?"}, {"id": "P-DRILL", "name": "Exercise & Drill Program", "type": "P", "change": "Keep", "what": "Tabletop exercises and grounding drills before each season, now run across agencies.", "pa": "AF-REHEARSE", "sa": "AF-REDUN", "layer": "Shared base", "why": "No change.", "protos": "PT-FALLBACK, PT-EXERCISE, PT-PRIORITY", "q": null}, {"id": "P-CREW", "name": "Community Sensing Crews", "type": "P", "change": "Keep, new role", "what": "Trained local groups who plan and fly sensing missions over their own blocks. They can now file sensing requests into the shared queue.", "pa": "AF-PART", "sa": "AF-COVER", "layer": "Shared base", "why": "Residents as requesters, not only volunteers.", "protos": "PT-CREWS, PT-VERIFIED", "q": null}, {"id": "A-ANCHOR", "name": "Anchor Sensor Network", "type": "A", "change": "Keep", "what": "Fixed sensors at schools, clinics and libraries, building on CDPH's ~230 sensors. They check airborne readings and keep reporting in a grounding.", "pa": "AF-COVER", "sa": "AF-REDUN", "layer": "Shared base", "why": "No change. Other agencies can use the same host sites.", "protos": "PT-ANCHOR, PT-FALLBACK, PT-PODS, PT-INSPECT, PT-VERIFIED, PT-MANDATE, PT-HUBS", "q": null}, {"id": "A-POD", "name": "Health Sensor Pod", "type": "A", "change": "Redesign", "what": "CDPH's own sensor-only pod, built to the city payload standard and carried as an add-on on operators', partners' or crews' flights.", "pa": "AF-COVER", "sa": "AF-SHARE", "layer": "Shared base", "why": "Now one entry on the add-on menu, built to the shared spec. A shared multi-sensor pod lets one flight serve several agencies.", "protos": "PT-PODS, PT-CREWS, PT-VERIFIED, PT-MANDATE, PT-HUBS", "q": null}, {"id": "A-UAS", "name": "Drones & Onboard Sensors", "type": "A", "change": "Keep", "what": "The aircraft and what they already carry: flight logs, wind and weather, navigation cameras.", "pa": "AF-COVER", "sa": "AF-SHARE", "layer": "Shared base", "why": "Clarified: delivery drones do not carry health sensors on their own. What they already have feeds the ledger, the burden budget and forecasting.", "protos": "PT-ANCHOR, PT-TERMS (new)", "q": null}, {"id": "A-SIGN", "name": "Ambient Public Displays", "type": "A", "change": "Keep", "what": "Signs at bus stops, libraries and community centers that show the record, with no sign-up or tracking.", "pa": "AF-SHOW", "sa": "AF-TRACE", "layer": "Shared base", "why": "Now shows the flight ledger too.", "protos": "PT-RECORD", "q": null}, {"id": "A-CACHE", "name": "Supply Caches", "type": "A", "change": "Keep", "what": "Filters, cooling kits, tests and medicine stored at host sites in priority neighborhoods.", "pa": "AF-MOBIL", "sa": "AF-COVER", "layer": "Agency use", "why": "No change. CDPH's own.", "protos": "PT-ANCHOR, PT-MESSENGER, PT-WATCH", "q": null}, {"id": "D-TWIN", "name": "City Base Map", "type": "D", "change": "Redesign", "what": "One map of Chicago that every agency reads from. It holds only the common ground: the grid, time, data format, where each reading came from and its purpose label.", "pa": "AF-SHARE", "sa": "AF-GAPS", "layer": "Shared base", "why": "Was CDPH's Neighborhood Twin with the burden overlay built in. The Mural: \"generic as a base map with layers, not as a health model.\" The health picture moves to D-HLAYER.", "protos": "BASE-TWIN, every prototype", "q": null}, {"id": "D-HLAYER", "name": "CDPH Health Layer", "type": "D", "change": "New (split)", "what": "CDPH's layer on the base map: health readings, the burden overlay, anomaly detection and the analysts' console.", "pa": "AF-DETECT", "sa": "AF-COVER", "layer": "Agency use", "why": "Split from the Twin. Other agencies see it only through the access rules.", "protos": "PT-INSPECT, PT-WATCH, PT-MEMORY", "q": null}, {"id": "D-SIM", "name": "Scenario Simulator", "type": "D", "change": "Keep", "what": "Runs hazard and airspace-decision scenarios on the base map.", "pa": "AF-REHEARSE", "sa": "AF-AIRSPACE", "layer": "Shared base", "why": "No change. Each agency keeps its own scenario library.", "protos": "PT-CORRIDOR, PT-WATCH, PT-EXERCISE", "q": null}, {"id": "D-RECORD", "name": "Open Record & Flight Ledger", "type": "D", "change": "Redesign", "what": "One public place showing who flew over each neighborhood, when, for whom and why, what was collected, who looked at it, and what was done about it.", "pa": "AF-TRACE", "sa": "AF-SHOW", "layer": "Governance", "why": "Was a record of readings and responses. Now the ledger the Mural asked for, so residents can read the airspace. The ledger is itself sensitive and follows its own access rules.", "protos": "PT-RECORD, PT-TRUST, PT-INSPECT, PT-VERIFIED, PT-MANDATE, PT-HUBS", "q": null}, {"id": "D-REPORT", "name": "Resident Report Channel", "type": "D", "change": "Keep", "what": "One place for residents to report, correct, challenge or ask for sensing.", "pa": "AF-PART", "sa": "AF-RELY", "layer": "Shared base", "why": "Requests now go into the shared tasking queue.", "protos": "PT-TASKDESK, PT-INSPECT, PT-VERIFIED", "q": null}, {"id": "D-ALERT", "name": "Opt-in Alerts & Action Cards", "type": "D", "change": "Keep", "what": "Phone alerts for a chosen area, each naming one thing to do and where.", "pa": "AF-SHOW", "sa": "AF-MOBIL", "layer": "Shared base", "why": "No change.", "protos": "PT-RECORD, PT-MESSENGER, PT-PRIORITY", "q": null}, {"id": "D-TASK", "name": "Tasking Queue", "type": "D", "change": "Redesign", "what": "Routes each signal to the office that owns it. For the few flights that must be scheduled on purpose, it issues a ticket that states the purpose, who pays, why it should go first, how fine the data is and how long it is kept.", "pa": "AF-ALLOC", "sa": "AF-ROUTE", "layer": "Shared base", "why": "Most collection rides along on flights already happening and needs no queue. The ticket handles the rest: steering, on-demand tasking. One ticket carries the purpose, the cost and the priority together.", "protos": "PT-TASKDESK, PT-PRIORITY", "q": null}, {"id": "D-MEMORY", "name": "Neighborhood Health Memory", "type": "D", "change": "Keep", "what": "Season-by-season archive of readings, signals and after-action records.", "pa": "AF-MEMORY", "sa": "AF-TRACE", "layer": "Shared base", "why": "No change. PT-MEMORY was eliminated, but the archive stays under the response loop.", "protos": "BASE-RESPONSE", "q": null}, {"id": "D-LINK", "name": "External Feeds & Remote ID", "type": "D", "change": "Redesign", "what": "Regional, federal and satellite feeds, plus FAA Remote ID broadcasts so the city can count flights it has no agreement with.", "pa": "AF-REDUN", "sa": "AF-BURDEN", "layer": "Shared base", "why": "We are not building drone detection; that is federal ground. But the ledger and the burden budget need to know what they cannot see.", "protos": "PT-FALLBACK", "q": "What share of flights over burdened blocks falls outside the system?"}, {"id": "R-BASE1", "name": "Ground Access Data Condition (Base 1)", "type": "R", "change": "New", "what": "Anyone using city launch sites, hubs or vertiports shares basic flight data: stored flight logs, planned routes and aircraft noise class. The data is delayed, kept at neighborhood level and has delivery endpoints removed.", "pa": "AF-SHARE", "sa": "AF-BURDEN", "layer": "Operator terms", "why": "The floor every operator meets. Enforced through hub siting (what was Bundle C). Small operators only ever face this level.", "protos": "PT-TERMS (new), PT-HUBS", "q": "Does Base 1 add anything beyond FAA Remote ID? If not, it spends goodwill for nothing."}, {"id": "R-XCHG", "name": "Data Exchange Terms (Base 2)", "type": "R", "change": "Redesign", "what": "Larger operators share richer sensor data, such as wind and temperature, and get back weather and corridor information pooled from everyone. A permit backstop applies if sharing fails.", "pa": "AF-PARTNER", "sa": "AF-SHARE", "layer": "Operator terms", "why": "Was CDPH's exchange. Now the city's second level. What operators get back may come from pooling everyone's Base 1 and Base 2 data: a picture no single operator could build.", "protos": "PT-TERMS (new), PT-CREDIT", "q": "Where is the line between Base 1 and Base 2, and what happens just below it?"}, {"id": "R-ADDON", "name": "Agency Add-on Menu", "type": "R", "change": "New", "what": "A fixed menu of extras an agency can ask operators for: carrying a pod, a detour through a thin area, imagery at a set privacy level. One front door to operators and a cap on how much any agency can ask.", "pa": "AF-PARTNER", "sa": "AF-ALLOC", "layer": "Operator terms", "why": "Every agency's ask spends the same goodwill. A menu makes asks comparable; a cap stops one agency using it up. Agencies pay for their own add-ons.", "protos": "PT-TERMS (new), PT-PODS, PT-CREDIT", "q": "How big is the cap, and who sets it?"}, {"id": "R-CRED", "name": "Coverage Credit", "type": "R", "change": "Redesign", "what": "Better terms for operators who carry sensors over thin or high-burden neighborhoods. Now an item on the add-on menu.", "pa": "AF-COVER", "sa": "AF-PARTNER", "layer": "Operator terms", "why": "Moves from CDPH's tool to a menu item any agency can use. CDPH has to ask and pay for burden-weighted steering; equity does not arrive by itself.", "protos": "PT-CREDIT, PT-PODS", "q": null}, {"id": "R-BUY", "name": "Data Purchase Agreement", "type": "R", "change": "Option, never prototyped", "what": "An agency pays operators for set readings in set neighborhoods.", "pa": "AF-COVER", "sa": "AF-PARTNER", "layer": "Operator terms", "why": "Still an option, now listed on the menu. Least preferred: it spends money where the design otherwise spends conditions and exchange.", "protos": "none", "q": null}, {"id": "R-MOU", "name": "Interagency Flight Agreement", "type": "R", "change": "Option, never prototyped", "what": "Standing agreement for partner agencies to fly sensing missions for each other, not only during groundings.", "pa": "AF-PARTNER", "sa": "AF-REDUN", "layer": "Operator terms", "why": "Still an option. Needs a rule for the days when the lender needs its own fleet.", "protos": "PT-TASKDESK", "q": null}, {"id": "R-CARRIER", "name": "Carrier Eligibility", "type": "R", "change": "New", "what": "Who may carry a city payload or read from the base map, and on what conditions.", "pa": "AF-PURPOSE", "sa": "AF-ACCESS", "layer": "Operator terms", "why": "The carriers test (and Hayden AI's bus cameras in Chicago) shows how quickly a carrier built for one job becomes an enforcement tool.", "protos": "PT-PURPOSE (new)", "q": "Are police-operated drones excluded outright, or allowed under a label that can never feed enforcement?"}, {"id": "R-STD", "name": "Shared Data Standard", "type": "R", "change": "Redesign", "what": "One format for every feed, reduced to the coarsest level that works before it leaves the source. Base 1 flight data is delayed and stripped of delivery endpoints.", "pa": "AF-RELY", "sa": "AF-ACCESS", "layer": "Shared base", "why": "Adds the protections flight logs need: a delivery endpoint is a home, and a pharmacy delivery is health information.", "protos": "PT-CREDIT, PT-TRUST, PT-MANDATE, PT-HUBS", "q": null}, {"id": "R-PAYSTD", "name": "City Payload Standard", "type": "R", "change": "New", "what": "What can ride on a commercial drone: weight, power, mounting, privacy level (sensor-only or camera), and a shared multi-sensor pod.", "pa": "AF-SHARE", "sa": "AF-PURPOSE", "layer": "Shared base", "why": "The Mural's gap: \"Our data standard covers format, not hardware.\" Privacy levels also set how much a flight counts against the burden budget.", "protos": "PT-PODS, PT-TERMS (new)", "q": "Do payload changes need FAA approval for delivery aircraft?"}, {"id": "R-PURPOSE", "name": "Purpose Labels & Access Matrix", "type": "R", "change": "New", "what": "Every reading is labeled with why it was collected, how fine it is, how long it is kept and who collected it. A matrix says which agency sees which layer and how closely. Some uses are never allowed. Every look is written in the record.", "pa": "AF-PURPOSE", "sa": "AF-ACCESS", "layer": "Governance", "why": "The safeguard the CPD test showed we need most. \"Just share it\" is the default within a purpose, not across purposes.", "protos": "PT-PURPOSE (new), PT-TRUST", "q": "Who keeps the list of purposes so agencies cannot declare ones that are too broad?"}, {"id": "R-TRIG", "name": "Trigger Thresholds & Confirmation", "type": "R", "change": "Keep", "what": "Levels that open a response, confirmed by an epidemiologist and a health worker, and revised after each event.", "pa": "AF-DETECT", "sa": "AF-TRACE", "layer": "Agency use", "why": "No change. Each agency sets its own.", "protos": "PT-WATCH, PT-VERIFIED, BASE-RESPONSE", "q": null}, {"id": "R-PLAY", "name": "Response Playbooks", "type": "R", "change": "Keep", "what": "Pre-agreed steps for each hazard: who goes, with what, and where.", "pa": "AF-MOBIL", "sa": null, "layer": "Agency use", "why": "No change.", "protos": "BASE-RESPONSE", "q": null}, {"id": "R-GAP", "name": "Gap-Triggered Coverage", "type": "R", "change": "Redesign", "what": "When any layer shows too little data somewhere, a sensor or flight is sent. A protected share goes to the highest-burden neighborhoods first, paid from the base budget so no agency can outbid it.", "pa": "AF-GAPS", "sa": "AF-COVER", "layer": "Shared base", "why": "Brings back what PT-TASKDESK did: weak as a CDPH tool, strong as shared infrastructure. \"Gap\" now means thin data on any layer, so the protected share keeps equity in.", "protos": "PT-TASKDESK", "q": "Whose gap is filled first when two layers are thin in different places?"}, {"id": "R-FALLBK", "name": "Grounding Fallback Protocol", "type": "R", "change": "Keep", "what": "Standing agreements and a switch that turns on fallback sources when drones are grounded.", "pa": "AF-REDUN", "sa": "AF-PARTNER", "layer": "Shared base", "why": "No change. One fallback for every agency is cheaper than six.", "protos": "PT-FALLBACK", "q": null}, {"id": "R-REVIEW", "name": "Public Review & Sunset Clause", "type": "R", "change": "Keep", "what": "City Council re-approves the whole system on a set cycle; steward, panel and resident findings must be answered there.", "pa": "AF-TRACE", "sa": "AF-PART", "layer": "Governance", "why": "No change, but now reviews every agency's use together.", "protos": "PT-CORRIDOR, PT-CREWS, PT-TRUST, PT-RECORD, PT-HUBS", "q": null}, {"id": "R-NEWUSE", "name": "Rule for Adding Purposes", "type": "R", "change": "New", "what": "No new purpose joins the whole system without custodian review, a yes from the neighborhood panels where it is binding, a public vote and an end date.", "pa": "AF-PURPOSE", "sa": "AF-PART", "layer": "Governance", "why": "Hayden AI in Chicago: the data rules held, but the program grew from bus lanes to meters to street sweeping through ordinary budget decisions. Labels on readings cannot stop that; this rule can.", "protos": "PT-PURPOSE (new), PT-TRUST", "q": null}, {"id": "R-CORR", "name": "Neighborhood Burden Budget", "type": "R", "change": "Redesign", "what": "A cap on how much flying and sensing each neighborhood carries, counted across every agency. Camera flights count more than sensor-only flights. Corridors and launch sites are reviewed against it.", "pa": "AF-AIRSPACE", "sa": "AF-BURDEN", "layer": "Shared base", "why": "Was CDPH's corridor review. Now the city's rule for fair burden, because burden adds up across agencies and no single agency sees the total.", "protos": "PT-CORRIDOR, PT-HUBS", "q": "Does the cap limit delivery service in places that already have little?"}, {"id": "R-BURDEF", "name": "Burden Definition Process", "type": "R", "change": "New", "what": "How \"burden\" is defined and weighted. Builds on Chicago's EJ Index and its co-chaired data group, adding airspace measures: overflights, noise, camera exposure. CDPH brings the health part; the custodian board approves.", "pa": "AF-BURDEN", "sa": "AF-PART", "layer": "Governance", "why": "Residents and CDPH already defined burden together once (Cumulative Impact Assessment, 2022 to 2023). Building on it brings that trust along.", "protos": "PT-CORRIDOR, PT-TRUST", "q": "Agencies will argue over the definition. CPD may say crime is a burden too."}, {"id": "R-PRIOR", "name": "City Emergency Airspace Mode", "type": "R", "change": "Redesign", "what": "In a declared emergency the usual rules switch together: OEMC decides who flies first, costs move to the city, purposes widen for a set time, and an audit follows.", "pa": "AF-ALLOC", "sa": "AF-MOBIL", "layer": "Shared base", "why": "Was CDPH's health priority zone. Only one actor can hold a piece of airspace at a time, so it has to be the city's. CDPH writes its own criteria for asking.", "protos": "PT-PRIORITY", "q": null}, {"id": "R-PERMIT", "name": "Air Pollution Permit Conditions", "type": "R", "change": "Keep", "what": "CDPH's air pollution permits. Conditions can require facilities to fund monitoring of their own impacts, including airborne surveys near their fence line.", "pa": "AF-DETECT", "sa": "AF-TRACE", "layer": "Agency use", "why": "No change. Facilities sit outside the operator levels; the purpose label still applies to what they fund.", "protos": "PT-INSPECT, PT-MANDATE", "q": "Can permits require airborne monitoring? (unverified)"}, {"id": "R-AQZ", "name": "Air Quality Siting Review", "type": "R", "change": "Keep, new role", "what": "CDPH reviews the air quality study required when certain uses are sited (2022 Air Quality Zoning Ordinance) and recommends to the Zoning Administrator.", "pa": "AF-AIRSPACE", "sa": "AF-TRACE", "layer": "Shared base", "why": "New job: the hook that makes Base 1 enforceable at hubs and vertiports. This is CDPH's strongest lever as anchor tenant.", "protos": "PT-HUBS, PT-TERMS (new)", "q": "Does the ordinance cover vertiports and drone hubs? (unverified)"}, {"id": "R-INSPQ", "name": "Sensing-Directed Inspection Queue", "type": "R", "change": "Keep", "what": "Inspectors' daily list is ranked by sensed exceedances and burden, not only by complaints.", "pa": "AF-COVER", "sa": "AF-DETECT", "layer": "Agency use", "why": "No change. The core of CDPH's use case.", "protos": "PT-INSPECT, PT-VERIFIED, PT-MANDATE", "q": null}], "protos": [{"id": "PT-TERMS", "name": "Operator Terms Ladder", "change": "New", "layer": "Commons", "goal": "G-PREV Increased preventive capacity", "thesis": "Every agency gets a steady stream of airspace data without buying a fleet, because the city asks every operator for the same things at three levels: a basic flight record to use city ground sites, richer sensor data in trade for weather and corridor information, and a short menu of extras an agency can order.", "differs": "Data comes through conditions and trade, not purchase. One front door to operators instead of one per department.", "lead": "DTI as host, with CDPH's air quality siting review as the hook for Base 1", "core": "R-BASE1, R-XCHG, R-ADDON, R-AQZ, P-OPS", "sup": "R-PAYSTD, R-STD, A-UAS, P-HOST", "how": "1. A hub or vertiport is sited; CDPH's review attaches the Base 1 condition.\n2. Operators using city ground sites send flight logs, planned routes and noise class, delayed and with delivery endpoints removed.\n3. Larger operators opt into Base 2: wind and temperature data for pooled weather and corridor information.\n4. Agencies order extras from the add-on menu, within a cap, through one city desk.", "q": "Where is the line between Base 1 and Base 2? Does Base 1 add anything beyond Remote ID? Does the siting ordinance cover hubs?", "home": "1", "touch": [], "decision": "Carry, explore first", "why": "The terms are the exchange."}, {"id": "PT-PURPOSE", "name": "Purpose Labels & Access", "change": "New", "layer": "Commons", "goal": "G-POWER Community power", "thesis": "Residents can trust that a health reading stays a health reading, because every reading carries a label saying why it was collected, each agency sees only the layers its purpose allows, and no new purpose joins the system without the neighborhood panels and a public vote.", "differs": "Governs the data after it is collected and the system's purposes over time. The only concept that answers the Hayden AI lesson: data rules held while the program kept growing.", "lead": "Data Custodian Board, with DTI keeping the access log", "core": "R-PURPOSE, R-NEWUSE, R-CARRIER, P-PANEL", "sup": "P-TRUST, D-RECORD, R-STD", "how": "1. Each agency registers its purposes from a fixed list the board keeps.\n2. Every reading is labeled at collection: purpose, grain, how long it is kept, who collected it.\n3. The access matrix decides who sees which layer and how closely; every look is logged.\n4. A new purpose needs board review, a yes from panels where binding, a Council vote and an end date.", "q": "Are police-operated drones excluded as carriers? Who audits the purpose list so it stays narrow?", "home": "3", "touch": ["2"], "decision": "Carry into commons", "why": "Protects residents from drift; also sets what agencies may see of each other."}, {"id": "PT-BUDGET", "name": "Neighborhood Burden Budget", "change": "Redesign", "layer": "Commons", "goal": "G-EQUITY Environmental health equity", "thesis": "No block carries more than its share of the sky, because every flight from every agency counts against one budget per neighborhood, camera flights count more, and burden is defined with residents.", "differs": "Treats flights as the harm, across all agencies at once. Was CDPH reviewing corridors; now the city keeping one count.", "lead": "DTI keeps the count; CDPH and the Department of Environment bring the burden measures; the board approves", "core": "R-CORR, R-BURDEF, R-AQZ, D-LINK", "sup": "R-PAYSTD, D-SIM, D-RECORD, R-REVIEW, P-AIRAUTH", "how": "1. Burden is defined with residents, building on the EJ Index.\n2. Each neighborhood gets a budget.\n3. Base 1 logs and Remote ID count every flight, weighted by payload privacy level.\n4. Near the cap, new corridors and sites are reviewed and add-ons are refused or rerouted. The count is public.", "q": "Does a cap limit delivery service where there is already little? Will agencies agree on what counts as burden?", "home": "1", "touch": ["2", "3"], "decision": "Carry into commons", "why": "Burden limits are the price of access; it also settles agencies' combined burden and answers to residents."}, {"id": "PT-LEDGER", "name": "Open Record & Flight Ledger", "change": "Redesign", "layer": "Commons", "goal": "G-POWER Community power", "thesis": "Anyone can look up who flew over their block, when, for whom and why, what was collected, who looked at it and what was done, on a sign or online, because every agency's flights and data uses are posted in one place.", "differs": "Makes residents readers of the airspace, not only receivers of alerts.", "lead": "DTI publishes; the custodian board audits", "core": "D-RECORD, A-SIGN, D-LINK, R-STD", "sup": "D-ALERT, R-REVIEW, P-RES", "how": "1. Base 1 logs and tickets post flights by neighborhood after a delay.\n2. Each entry shows the purpose label and the agency.\n3. Every look at a layer is logged beside it.\n4. Signs and the web show it in plain words; residents can challenge an entry.", "q": "The ledger is itself a map of what the city watches. Who may see the full version?", "home": "3", "touch": ["2"], "decision": "Carry into commons", "why": "Residents read the airspace; agencies see each other's use."}, {"id": "PT-CUSTODIAN", "name": "Custodian Board & Neighborhood Panels", "change": "Redesign", "layer": "Commons", "goal": "G-POWER Community power", "thesis": "Each neighborhood decides what kinds of use its share of the sky goes to, because an independent board with resident seats holds the data and neighborhood panels approve uses by purpose, binding on cameras and enforcement.", "differs": "Power over purposes, not single uses. Keeps deciding (the board) apart from running (DTI).", "lead": "P-TRUST board with the neighborhood panels", "core": "P-TRUST, P-PANEL, R-BURDEF, R-REVIEW", "sup": "R-PURPOSE, D-RECORD, P-HOST", "how": "1. The board is seated by ordinance, resident seats from the highest-burden neighborhoods first.\n2. Panels form neighborhood by neighborhood.\n3. Panels approve purpose categories once a year; camera and enforcement-adjacent uses need their yes.\n4. The board approves the burden definition and audits the access log.", "q": "Does the board need an ordinance to have teeth? Who sits on a panel, and how is a neighborhood drawn?", "home": "3", "touch": [], "decision": "Carry, explore first", "why": "Residents decide purposes."}, {"id": "PT-GAPS", "name": "Gap-Triggered Coverage", "change": "Redesign", "layer": "Commons", "goal": "G-EQUITY Environmental health equity", "thesis": "Wherever the picture is thin, on any agency's layer, a sensor or flight is sent and the highest-burden neighborhoods get a protected share first, because one city queue issues tickets that state the purpose, who pays and why it goes first.", "differs": "The only concept that schedules collection on purpose. Most data rides along on flights already happening; this handles the rest.", "lead": "DTI tasking queue, with each agency's office and residents requesting", "core": "R-GAP, D-TASK, D-REPORT, P-FLEET", "sup": "R-MOU, P-CREW, P-EPI, D-RECORD", "how": "1. A layer shows thin data, or a resident or office asks.\n2. The queue issues a ticket: purpose, payer, basis for priority, grain, retention.\n3. The protected burden-weighted share is filled first from the base budget; other tickets wait their turn.\n4. The flight is posted to the ledger and counts against the burden budget.", "q": "Whose gap goes first when two layers are thin in different places? Who pays for residents' tickets?", "home": "2", "touch": ["1", "3"], "decision": "Carry, explore first", "why": "The shared queue; operators fly the tickets; residents can file them."}, {"id": "PT-EMERGENCY", "name": "City Emergency Airspace Mode", "change": "Redesign", "layer": "Commons", "goal": "G-PREV Increased preventive capacity", "thesis": "In a declared emergency the right flights get through first, because the city switches into one mode where OEMC decides who flies, costs move to the city, purposes widen for a set time and an audit follows.", "differs": "Priority decided by a named arbiter, not claimed by an agency.", "lead": "OEMC", "core": "R-PRIOR, P-OEMC, P-FLEET, D-TASK", "sup": "P-PREP, P-DRILL, D-ALERT, P-AIRAUTH, D-RECORD", "how": "1. An agency's criteria are met and it asks OEMC.\n2. OEMC declares the mode for an area and a time.\n3. OEMC ranks flights; partner fleets are shared by rule, not goodwill.\n4. The mode ends on its date and the audit is posted to the ledger.", "q": "Does health keep a protected share of the fleet? Will OEMC take the role?", "home": "2", "touch": [], "decision": "Carry, explore first", "why": "Settles who flies first between agencies."}, {"id": "PT-FALLBACK", "name": "Grounding Continuity Plan", "change": "Keep", "layer": "Commons", "goal": "G-PREV Increased preventive capacity", "thesis": "Every agency keeps getting readings when drones are grounded, because the city lines up backup sources once and practices the switch.", "differs": "Resilience from varied backup sources plus practice, not one strong backbone.", "lead": "DTI with each agency's preparedness staff", "core": "R-FALLBK, D-LINK, P-FLEET, P-DRILL", "sup": "A-ANCHOR", "how": "1. Partners sign fallback agreements once, for every agency.\n2. A grounding is declared and the switch turns fallbacks on.\n3. Regional, federal and satellite feeds and ground sites fill in.\n4. The switch is drilled before each season.", "q": null, "home": "2", "touch": [], "decision": "Carry into commons", "why": "One fallback instead of one per agency."}, {"id": "PT-INSPECT", "name": "Sensing-Directed Inspections", "change": "Keep", "layer": "CDPH use", "goal": "G-PREV Increased preventive capacity", "thesis": "Air inspections reach high-burden neighborhoods before exposure builds, because inspectors' daily list is ranked by sensed exceedances and burden, not only by complaints.", "differs": "Changes who gets inspected; acts through CDPH's own regulatory lever.", "lead": "P-INSP (air inspectors)", "core": "R-INSPQ, P-INSP, A-ANCHOR, D-HLAYER", "sup": "R-PERMIT, D-REPORT, D-RECORD", "how": "1. Anchor sites, pods and shared feeds flag exceedances near permitted facilities.\n2. The health layer ranks sites by exceedance and burden.\n3. Inspectors work the ranked list; complaints still enter it.\n4. What was inspected and found is posted.", "q": "With three inspectors, a better-ranked list is still a short one.", "home": "C", "touch": ["1", "2", "3"], "decision": "Carry as CDPH use", "why": "The worked case: draws on all three (see below). Home: CDPH's own use."}, {"id": "PT-MANDATE", "name": "Permit-Required Airspace Monitoring", "change": "Keep", "layer": "CDPH use", "goal": "G-PREV Increased preventive capacity", "thesis": "Blocks next to permitted facilities get regular airborne readings paid for by the facility, because CDPH writes pod flights or plume surveys, with data sent straight to CDPH, into air permits.", "differs": "The polluter pays for the evidence, through CDPH's own permits.", "lead": "P-INSP (permit writers)", "core": "R-PERMIT, A-POD, R-STD, P-INSP", "sup": "P-OPS, A-ANCHOR, D-RECORD, R-INSPQ", "how": "1. At issue or renewal, major-source permits require a monitoring plan.\n2. Approved operators fly CDPH pods on a set schedule, paid by the facility.\n3. Readings go straight to CDPH, labeled for this purpose only.\n4. Exceedances move the facility up the inspection list.", "q": "Can permits require airborne monitoring? (unverified)", "home": "1", "touch": ["3"], "decision": "Hold: team's call", "why": "Facilities pay for evidence through permits; readings are published."}, {"id": "PT-VERIFIED", "name": "Resident-Verified Readings", "change": "Keep, new role", "layer": "CDPH use", "goal": "G-POWER Community power", "thesis": "Residents near pollution sources can move an inspection up the list with measured evidence rather than a complaint, because CDPH accepts readings from trained crews and must answer within a set time.", "differs": "Residents supply measurements and hold a right to a response.", "lead": "P-CREW, with P-INSP answering", "core": "P-CREW, A-POD, D-REPORT, R-INSPQ, R-TRIG", "sup": "P-CHW, D-RECORD, A-ANCHOR, D-TASK", "how": "1. Crews near facilities carry or fly CDPH's calibrated pods.\n2. A reading is submitted and checked against anchor sites.\n3. A verified exceedance obliges a response within a set time.\n4. The answer is posted to the ledger.", "q": "Can CDPH meet a response deadline with its current staff?", "home": "3", "touch": [], "decision": "Hold: team's call", "why": "A resident's measurement creates a duty to answer."}, {"id": "PT-CREWS", "name": "Community-Flown Sensing Crews", "change": "Keep, new role", "layer": "CDPH use", "goal": "G-POWER Community power", "thesis": "Residents of high-burden neighborhoods measure their own air and heat and read it with health workers they know, because CDPH trains, certifies and equips local groups to fly.", "differs": "Residents do the measuring and decide when and where flights happen.", "lead": "Local groups with CHWs; CDPH trains and clears missions", "core": "P-CREW, A-POD, P-RELAY, P-CHW", "sup": "R-REVIEW, D-TASK", "how": "1. Groups are recruited, trained and certified.\n2. Each plans missions with its health worker.\n3. Missions are cleared and counted against the burden budget.\n4. Readings go to the health layer and back to the group.", "q": "Coverage follows strong groups. How do quieter blocks get crews?", "home": "3", "touch": ["2"], "decision": "Carry as CDPH use", "why": "Residents measure; crews can serve other agencies' layers."}, {"id": "PT-ANCHOR", "name": "Anchor Site Network", "change": "Keep", "layer": "CDPH use", "goal": "G-EQUITY Environmental health equity", "thesis": "Residents of the highest-burden neighborhoods get air readings that never go dark, because CDPH makes fixed sensors at schools, clinics and libraries the backbone and treats drones as the supplement.", "differs": "Ground first: a grounding costs detail, not coverage.", "lead": "P-INSP (environmental-health specialist)", "core": "A-ANCHOR, A-CACHE, P-INSP", "sup": "A-UAS, D-HLAYER", "how": "1. Neighborhoods are ranked by burden and host sites chosen.\n2. Sensors and supplies go in at those sites.\n3. Sites report all the time; airborne readings are checked against them.\n4. Other agencies can put their own sensors at the same sites.", "q": "Chicago's earlier bus-shelter sensor network was abandoned. What keeps this one maintained?", "home": "C", "touch": ["2"], "decision": "Carry as CDPH use", "why": "CDPH's ground backbone; host sites shareable."}, {"id": "PT-STEER", "name": "Burden-Weighted Steering", "change": "Redesign", "layer": "CDPH use", "goal": "G-EQUITY Environmental health equity", "thesis": "Thin, high-burden neighborhoods get covered within days, because CDPH orders a detour add-on from the city menu and pays operators in better terms to carry its pods over those blocks.", "differs": "Equity does not arrive by itself in a shared system. This is CDPH asking, and paying, for it.", "lead": "CDPH data team", "core": "R-CRED, R-ADDON, A-POD, P-OPS", "sup": "D-HLAYER, R-PAYSTD", "how": "1. The health layer marks thin, high-burden blocks.\n2. CDPH orders a detour add-on through the city desk, within its cap.\n3. Operators route pod-carrying flights over those blocks for better terms.\n4. Flights count against the burden budget.", "q": "How much of the cap and the budget does CDPH need for this?", "home": "1", "touch": [], "decision": "Hold: team's call", "why": "CDPH paying operators for equity."}, {"id": "PT-PODS", "name": "Health Sensor Pods", "change": "Redesign", "layer": "CDPH use", "goal": "G-EQUITY Environmental health equity", "thesis": "High-burden neighborhoods get the measurements their risks call for, because CDPH's sensor-only pods, built to the city payload standard, ride on routine flights, often inside a shared pod with other agencies' sensors.", "differs": "CDPH owns the instrument, not the aircraft, and decides what is measured.", "lead": "CDPH data team running the pod program", "core": "A-POD, R-PAYSTD, R-ADDON, P-OPS", "sup": "A-ANCHOR", "how": "1. CDPH builds its pod to the city standard and publishes what it can and cannot capture.\n2. Pods are placed by neighborhood need.\n3. Operators carry them as an add-on, often in a shared pod.\n4. Readings go to the health layer, labeled for health use.", "q": "Do payload changes need FAA approval on delivery aircraft?", "home": "1", "touch": ["2"], "decision": "Carry as CDPH use", "why": "An add-on bought through the terms; shared pods serve several agencies."}, {"id": "PT-WATCH", "name": "Automated Scenario Watch", "change": "Keep", "layer": "CDPH use", "goal": "G-PREV Increased preventive capacity", "thesis": "The neighborhoods likely to be hit first have supplies and a playbook in place before a threshold is crossed, because the shared simulator runs the matching scenario on CDPH's health layer the moment a change appears.", "differs": "Simulation as a standing reflex; people only confirm the dispatch.", "lead": "The simulator, with an epidemiologist and a CHW confirming", "core": "D-SIM, A-CACHE, R-TRIG, D-HLAYER", "sup": "P-UNIV", "how": "1. The health layer flags a sudden change.\n2. The simulator runs the matching scenario.\n3. Supplies and playbooks are staged where it predicts.\n4. People confirm, and the result is logged.", "q": "A wrong forecast moves supplies to the wrong place.", "home": "C", "touch": ["2"], "decision": "Carry as CDPH use", "why": "CDPH's scenarios on the shared simulator."}, {"id": "PT-EXERCISE", "name": "Scenario Exercise Program", "change": "Keep", "layer": "CDPH use", "goal": "G-PREV Increased preventive capacity", "thesis": "Health workers, residents and partner agencies know their parts before an emergency, because CDPH walks through each scenario with them and resets thresholds from what they find.", "differs": "People practice the scenarios, rather than the simulator running them alone.", "lead": "P-PREP with the university partner", "core": "P-DRILL, D-SIM, P-UNIV, P-PREP", "sup": "P-CHW, P-OEMC", "how": "1. Before each season a scenario is picked, often with CFD and OEMC.\n2. It runs on the simulator.\n3. Participants walk through the playbook, including the emergency mode.\n4. Gaps revise playbooks and thresholds.", "q": null, "home": "2", "touch": ["3"], "decision": "Carry as CDPH use", "why": "Agencies rehearse the shared rules together; residents take part."}, {"id": "PT-MESSENGER", "name": "Trusted Messenger Network", "change": "Keep", "layer": "CDPH use", "goal": "G-POWER Community power", "thesis": "Residents hear how their area is read, and what to do, from a health worker or local group they already know, and those groups hold supplies and a role when a response opens.", "differs": "Transparency and readiness live in trusted organizations, not signs, votes or models.", "lead": "P-CHW with the Community Relay", "core": "P-CHW, P-RELAY, A-CACHE", "sup": "D-ALERT", "how": "1. Health workers read the health layer on a schedule.\n2. They bring findings to residents through local groups, each with one action.\n3. When a response opens, groups take their role and supplies.\n4. What residents say comes back into the record.", "q": "Reaches people connected to local groups more than people who are not.", "home": "C", "touch": ["3"], "decision": "Hold: team's call", "why": "CDPH's response layer, carried by trusted local groups."}, {"id": "BASE-MAP", "name": "City Base Map", "change": "Shared base", "layer": "Commons", "goal": "", "thesis": "One map of Chicago every agency reads from: grid, time, data format, where each reading came from, purpose label.", "differs": "", "lead": "", "core": "D-TWIN, P-UNIV, P-HOST", "sup": "", "how": "", "q": "", "home": "2", "touch": [], "decision": "Shared base (not scored)", "why": "What every agency reads from."}, {"id": "BASE-HEALTH", "name": "CDPH Health Layer & Response Loop", "change": "Shared base", "layer": "CDPH use", "goal": "", "thesis": "CDPH's picture on the base map, plus thresholds, playbooks and after-action memory. Replaces BASE-TWIN and BASE-RESPONSE.", "differs": "", "lead": "", "core": "D-HLAYER, R-TRIG, R-PLAY, P-XDEPT, D-MEMORY", "sup": "", "how": "", "q": "", "home": "C", "touch": [], "decision": "Shared base (not scored)", "why": ""}]};
