DATA.aff.forEach(a=>A[a[0]]={id:a[0],name:a[1],what:a[2],crit:a[3],goals:sp(a[4]),arch:a[5],change:a[6],imps:sp(a[7]),kind:"a"});
DATA.imp.forEach(m=>I[m[0]]={id:m[0],name:m[1],what:m[2],un:m[3]==="Unintended",serves:sp(m[4]),against:sp(m[5]),driven:sp(m[6]),check:m[7],arch:m[8],change:m[9],kind:"i"});
