function outerAffs(id){const o=outer()[id];return state.ring==="feat"?[o.pa,o.sa].filter(Boolean):o.affs}
function outerPrimary(id){const o=outer()[id];return state.ring==="feat"?[o.pa].filter(Boolean):o.affs}
