  if(state.ring==="feat") outs.forEach(o=>{const pa=F[o]&&F[o].pa;if(pa&&!lit.has(o)){soft.add(pa);paths.push([o,pa,"p-soft"])}});
  else outs.forEach(o=>{if(!lit.has(o))P[o].affs.forEach(a=>{if(lit.has(a))paths.push([o,a,"p-soft"])})});
  M.risks.forEach(([u,c])=>{lit.add(u);const ck=state.ring==="feat"?c:(PCHECKS[u]||[]).find(p=>outs.includes(p))||(PCHECKS[u]||[])[0];if(ck){lit.add(ck);paths.push([ck,u,"p-check"])}
    I[u].driven.forEach(a=>{if(lit.has(a)||soft.has(a))paths.push([a,u,"p-risk"])});I[u].against.forEach(g=>{lit.add(g);paths.push([u,g,"p-risk"])})});
