// ---------- render ----------
function render(){
  const focusId=state.hover||state.pin;let S=null;
  if(focusId&&XY[focusId]&&NODE[focusId]) S=neighborhood(focusId);
  else if(state.focus&&state.focus.type==="moment") S=momentSet(MOMENTS.find(m=>m.id===state.focus.id));
  else if(state.focus&&state.focus.type==="lens") S=lensSet(LENSES.find(l=>l.id===state.focus.id));
  svg.classList.toggle("dim",!!S);
  Object.entries(NODE).forEach(([id,g])=>{if(!g.isConnected)return;g.classList.toggle("lit",!!S&&S.lit.has(id));g.classList.toggle("soft",!!S&&S.soft.has(id)&&!S.lit.has(id));
    const lk=g.dataset.layer;g.classList.toggle("layer-off",!!lk&&!state.layers.has(lk));
    if(I[id]&&I[id].un) g.style.display=state.risks?"":"none"});
  baseLinks.forEach(l=>{const un=I[l.a]&&I[l.a].un||I[l.b]&&I[l.b].un;l.p.style.display=(un&&!state.risks)?"none":""});
  gHL.innerHTML="";
  if(S){const seen=new Set();S.paths.forEach(([a,b,c])=>{if(!XY[a]||!XY[b])return;if(!state.risks&&((I[a]&&I[a].un)||(I[b]&&I[b].un)))return;
    const lk=(NODE[a]&&NODE[a].dataset.layer)||(NODE[b]&&NODE[b].dataset.layer);if(lk&&!state.layers.has(lk))return;
    const k=a+">"+b+c;if(seen.has(k))return;seen.add(k);el("path",{d:curve(a,b),class:c},gHL)})}
  syncControls();renderPanel()}
// ---------- tooltip ----------
const tipEl=document.getElementById("tip"),stage=document.getElementById("stage");
function tip(id,e){const it=lookup(id);if(!it)return;const r=stage.getBoundingClientRect();
  tipEl.innerHTML=`<div class="eyebrow">${kindName(it)} · ${id}</div><b>${esc(it.name)}</b>${esc(short(it))}`;tipEl.hidden=false;
  let x=e.clientX-r.left+14,y=e.clientY-r.top+14;if(x>r.width-270)x=e.clientX-r.left-274;tipEl.style.left=x+"px";tipEl.style.top=y+"px"}
